import{_ as s,l as n,o as e,c as i,v as r,p as l,x as o,d as p,i as h,S as m}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"Sora 2 与 Sora App","description":"","frontmatter":{"title":"Sora 2 与 Sora App","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sora-2.md","filePath":"llm/sora-2.md","lastUpdated":1789023840000}'),d={name:"llm/sora-2.md"};function A(c,a,E,S,u,g){const t=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="sora-2-与-sora-app" tabindex="-1">Sora 2 与 Sora App <a class="header-anchor" href="#sora-2-与-sora-app" aria-label="Permalink to &quot;Sora 2 与 Sora App&quot;">​</a></h1><div class="epigraph"><p>新一代视频与音频生成更符合物理直觉、更可控，并带同步对白与音效；创作入口是一同发布的 Sora 应用。</p><footer>—— OpenAI，Sora 2 is here，2025-09-30</footer></div><p>OpenAI 在 2025 年 9 月 30 日发布 <strong>Sora 2</strong>：官方博客称为旗舰视频与音频生成模型，相对前代更强调物理准确性、真实感与可控性，并<strong>原生带同步对白与音效</strong>。同日推出 iOS 应用，名称就是 <strong>Sora</strong>：创作、remix 他人生成、在可定制信息流里发现视频，以及 <strong>cameo / characters</strong>——一次应用内音视频核验后，把本人形象放入生成场景。ChatGPT Pro 用户可在 sora.com 使用实验性更高质量的 <strong>Sora 2 Pro</strong>；博客还写计划提供 API，Sora 1 Turbo 暂时保留。闭源视频模型只引公开博客与产品叙述，不引用非官方层数或训练配方。官方页面后来注明：截至 <strong>2026 年 4 月 26 日</strong>，Sora 产品已不可用——写能力时要标发布稿日期，写现状时要标下线公告，二者不要混成「2026 年 9 月仍可下载」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>2024 年 2 月的 <a href="/llm/sora">Sora</a> 技术博客把模型写成时空 patch 上的文本条件扩散，并坦陈物理、因果、长时一致性等失败。产品侧长期是无声或弱同步的画面，创作者要后期配音。<a href="/llm/veo-3">Veo 3</a> 在 2025 年 5 月把原生音频写成主轴。Sora 2 要公开回答的产品问题是：同一生成过程里画面是否更守常识物理、声音是否对齐、用户是否能在社交信息流里创作与再创作，而不是只在研究页看样片。</p><p>第二个问题是<strong>产品与模型同名</strong>。口语里的 Sora 2 可能指模型，也可能指应用。博客把部署写成：美国与加拿大先开放 iOS 邀请，随后可在 sora.com 使用；免费档有额度限制，受算力约束；Pro 走更高质量档。Cameo 把肖像权与核验做成功能，而不是技术报告里的身份编码器公式。没有公开的 DiT 层表、数据配比或采样器。把第三方「拆解」写进本篇，会越过官方合同。</p><h3 id="世界模拟器修辞仍是观察-不是规格" tabindex="-1">世界模拟器修辞仍是观察，不是规格 <a class="header-anchor" href="#世界模拟器修辞仍是观察-不是规格" aria-label="Permalink to &quot;世界模拟器修辞仍是观察，不是规格&quot;">​</a></h3><p>第一代博客用 3D 一致性与物体持久论证缩放视频通向模拟器。Sora 2 发布稿改口风为物理更好、可控更好、带声，并给滑板一类样片叙事。这仍是定性能力列表。失败模式不会因为改名而消失：长镜头一致性、文字、复杂多人交互，公开材料没有给出可复现基准表。应用层的 remix 与信息流，是分发与激励结构，不是新的动力学引擎。把信息流热度写成物理已解决，是类别错误。</p><p><span class="marginnote">引用发布稿时写 2025-09-30。引用产品存续时写官方「as of April 26, 2026, the Sora product is no longer available」。API 是否另有关停日程以当时开发者公告为准，不在本篇发明日期。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>公开方法只能按产品能力写。生成：文本（及产品允许的图像等条件）→ 带音频的视频。相对 Sora 1 的宣传差：物理更准、真实感、指令遵从、声画同步。应用：垂直信息流、remix、来自短核验录像的 cameo。访问：邀请制免费探索 + Pro 的 Sora 2 Pro；计划中的 API 与 1 Turbo 并存于发布当日叙述。安全与责任：官方另有 <em>Launching Sora responsibly</em> 一类同期材料，谈水印、来源与肖像控制——具体开关以当时帮助中心为准，本篇不把未公开的分类器结构写进模型。</p><p>与 2024 年技术博客的衔接：第一代给出统一时空表示的方法学；第二代发布稿<strong>不再复述</strong>压缩网络与 patch 网格，只给能力与应用。因此架构段落应指向前作，并标明 2.0 <strong>未公开</strong>是否同一骨干。比较 Veo 3、<a href="/llm/seedance-2">Seedance 2.0</a> 时，只比双方当时写过的：时长、是否原生音频、入口产品，不比未公开的损失曲线。</p>',12)),(e(),l(m,null,{default:o(()=>[h(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E6%96%87%E6%9C%AC%20%2F%20%E4%BA%A7%E5%93%81%E5%85%81%E8%AE%B8%E7%9A%84%E8%A7%86%E8%A7%89%E6%9D%A1%E4%BB%B6%22%5D%20--%3E%20M%5B%22Sora%202%20%E7%94%9F%E6%88%90%EF%BC%88%E5%AE%98%E6%96%B9%EF%BC%9A%E8%A7%86%E9%A2%91%2B%E5%90%8C%E6%AD%A5%E9%9F%B3%E9%A2%91%EF%BC%89%22%5D%0A%20%20M%20--%3E%20V%5B%22%E5%B8%A6%E5%A3%B0%E7%9F%AD%E7%89%87%22%5D%0A%20%20V%20--%3E%20APP%5B%22Sora%20%E5%BA%94%E7%94%A8%EF%BC%9A%E4%BF%A1%E6%81%AF%E6%B5%81%20%C2%B7%20remix%22%5D%0A%20%20ID%5B%22%E4%B8%80%E6%AC%A1%E6%80%A7%E9%9F%B3%E8%A7%86%E9%A2%91%E6%A0%B8%E9%AA%8C%22%5D%20--%3E%20C%5B%22cameo%20%2F%20characters%22%5D%0A%20%20C%20--%3E%20APP%0A%20%20APP%20--%3E%20R%5B%22%E5%86%8D%E7%94%9F%E6%88%90%20%2F%20%E5%86%8D%E6%B7%B7%E5%90%88%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h3 id="cameo-是身份核验产品-不是开源人脸算法" tabindex="-1">Cameo 是身份核验产品，不是开源人脸算法 <a class="header-anchor" href="#cameo-是身份核验产品-不是开源人脸算法" aria-label="Permalink to &quot;Cameo 是身份核验产品，不是开源人脸算法&quot;">​</a></h3><p>博客写明：在应用内录一段音视频以核验身份并采集形象，然后可把自己放入场景；也描述朋友使用形象的社交玩法。设计意图是降低「任意上传一张陌生人照片就生成」的滥用，把控制权收到核验过的形象槽。这不能写成已解决深度伪造：核验流程、水印与滥用举报是政策与产品，公式未公开。写本篇只陈述官方功能边界，不讨论如何绕过核验。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>能讨论的机制只有官方承认的输入输出合同。原生音频意味着时间上的声画联合：动作与音效、口型与对白在同一生成里对齐，消除「先出无声片再配音」的产品缝。物理更好，表示接触、重力、动量在观感上更少明显穿帮，<strong>不是</strong>可查询的牛顿求解器。可控更好，表示提示中的镜头与事件更常被遵守。Remix 把已生成视频当成新提示的条件，形成社交图上的再生成，而不是时间上可交互的世界模型——后者见 <a href="/llm/genie-3">Genie 3</a>。</p><p>信息流与推荐是应用机制：模型产出片段，排序模型决定看见谁。这会改变何种失败被放大（物理尚可但肖像争议的内容）。发布稿把算力约束与免费额度写在一起，说明生成仍是稀缺资源，不是无限实时引擎。下线公告则说明：能力叙事与服务存续是两件事；研究引用应绑博客日期。</p><p><span class="marginnote">不要把 2024 年 <em>Video generation models as world simulators</em> 的 patch 公式倒填进 Sora 2。也不要把 2026 年 4 月的产品下线写成「模型从未发布」。三套日期：2024-02 方法学、2025-09-30 产品发布、2026-04-26 产品不可用。</span></p><h3 id="评测只有定性样片时-不要编排行榜" tabindex="-1">评测只有定性样片时，不要编排行榜 <a class="header-anchor" href="#评测只有定性样片时-不要编排行榜" aria-label="Permalink to &quot;评测只有定性样片时，不要编排行榜&quot;">​</a></h3><p>官方以样片与描述为主，没有与 Sora 1 同表的公开 FVD 或人类偏好百分比写进该篇发布稿。第三方 Arena 分数若出现，要写清日期、是否带声、提示集，且不是 OpenAI 的合同。本仓库对闭源视频模型的纪律不变：公开博客为准。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><h3 id="应用关闭后-引用要改成历史产品" tabindex="-1">应用关闭后，引用要改成历史产品 <a class="header-anchor" href="#应用关闭后-引用要改成历史产品" aria-label="Permalink to &quot;应用关闭后，引用要改成历史产品&quot;">​</a></h3><p>2026 年 9 月写这篇，主叙述仍是 2025 年 9 月发布稿里的架构与产品设计，并加一句官方下线。不要指导读者去已经关闭的应用「如何上手」。API 与权重是否以任何形式残留，以当时 OpenAI 公告为准。肖像、版权、青少年保护属于责任博客与法律，不是生成公式。水印与 C2PA 若在责任文中出现，与 Google 的 SynthID 叙事同类：来源标记，不是防伪证明。</p><p>与交互世界模型分清：Sora 2 生成的是固定时间轴的带声视频（可 remix 成新片），用户不能在生成过程中用键盘连续导航。Genie 3 才把实时交互写成 24 fps 世界。与实时通话里的摄像头流（<a href="/llm/realtime-video-interaction">实时视频交互</a>）也不同：那是理解与语音，不是文生视频。</p><p><span class="marginnote">出处：OpenAI，<em>Sora 2 is here</em>（2025-09-30）及页面上的产品状态说明；方法学对照 2024-02-15 <em>Video generation models as world simulators</em>。责任对照同期 Launching Sora responsibly。仅公开博客。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Sora 2 是 2025-09-30 发布的带同步音频的旗舰视频模型，强调物理、真实感与可控。</li><li>Sora 应用提供信息流、remix 与核验后的 cameo；与模型同名但不是同一对象。</li><li>无公开骨干细节；2024 年 patch 扩散文不可倒填。</li><li>官方称 2026-04-26 起该产品不可用，引用须分发布与存续。</li><li>出处：OpenAI Sora 2 发布博客。</li></ul>',15))])}const _=s(d,[["render",A]]);export{B as __pageData,_ as default};
